// src/identity/assertion.ts
// ---------------------------------------------------------------------------
// Proof that the site, not the page, says who this visitor is.
//
// A link request arrives from the browser carrying the site key, and the site
// key names the SITE. Anything the page can send, anyone with the page can send,
// so with the site key alone a visitor could claim any account id and be handed
// that person's profile. The site's backend knows who is signed in; it signs
// the claim, the page carries the signature, and the worker checks it.
//
// The assertion is an HMAC-SHA256 over exactly what is being asserted:
//
//     tenant \n visitorId \n accountId \n exp
//
// keyed by the tenant's identity secret and encoded base64url. `exp` is unix
// seconds; a signature is good until then and no longer than a day. A secret
// per tenant, in IDENTITY_SECRETS as `tenant:secret[|previous],tenant2:secret`,
// with `|` allowing two to be valid during a rotation.
//
// When a tenant has NO secret configured, a link is accepted on the site key
// alone and the record says so (`assurance: 'site'`). That is the demo setting.
// A deployment that handles real accounts sets the secret, at which point an
// unsigned link is refused; the assurance level is on every link record so a
// reader of the warehouse can tell the two apart.
// ---------------------------------------------------------------------------

import type { TenantId } from '@/tenancy/tenant';

export const ASSERTION_MAX_TTL_S = 24 * 3600;

export type Assurance = 'signed' | 'site';

export function secretTable(env: { IDENTITY_SECRETS?: string }): Map<string, string[]> {
  const table = new Map<string, string[]>();
  for (const entry of (env.IDENTITY_SECRETS ?? '').split(',')) {
    const i = entry.indexOf(':');
    if (i < 0) continue;
    const tenant = entry.slice(0, i).trim();
    const secrets = entry.slice(i + 1).split('|').map((s) => s.trim()).filter(Boolean);
    if (!tenant || secrets.length === 0) continue;
    table.set(tenant, [...(table.get(tenant) ?? []), ...secrets]);
  }
  return table;
}

/** The secrets that may sign for a tenant: its own, plus any under `*`. */
export function secretsFor(env: { IDENTITY_SECRETS?: string }, tenant: TenantId): string[] {
  const table = secretTable(env);
  return [...(table.get(tenant) ?? []), ...(table.get('*') ?? [])];
}

export function assertionMaterial(tenant: TenantId, visitorId: string, accountId: string, exp: number): string {
  return `${tenant}\n${visitorId}\n${accountId}\n${exp}`;
}

function b64url(bytes: ArrayBuffer): string {
  let s = '';
  for (const b of new Uint8Array(bytes)) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

async function hmac(secret: string, material: string): Promise<string> {
  const key = await crypto.subtle.importKey(
    'raw', new TextEncoder().encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'],
  );
  return b64url(await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(material)));
}

/** What the site's backend computes. Exported so a test, and a reference integration, can mint one. */
export async function signAssertion(
  secret: string, tenant: TenantId, visitorId: string, accountId: string, exp: number,
): Promise<string> {
  return hmac(secret, assertionMaterial(tenant, visitorId, accountId, exp));
}

function equalStrings(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

export type AssertionVerdict =
  | { ok: true; assurance: Assurance }
  | { ok: false; reason: string };

/**
 * Decide whether a link may proceed. Signed when the tenant has a secret and
 * the signature checks; site-assured when the tenant has no secret at all;
 * refused otherwise.
 */
export async function verifyAssertion(
  env: { IDENTITY_SECRETS?: string },
  tenant: TenantId,
  claim: { visitorId: string; accountId: string; exp?: number; assertion?: string },
  nowMs = Date.now(),
): Promise<AssertionVerdict> {
  const secrets = secretsFor(env, tenant);
  if (secrets.length === 0) return { ok: true, assurance: 'site' };

  if (!claim.assertion) return { ok: false, reason: 'identity assertion required for this tenant' };
  const exp = claim.exp;
  if (typeof exp !== 'number' || !Number.isFinite(exp)) return { ok: false, reason: 'assertion exp missing' };
  const nowS = Math.floor(nowMs / 1000);
  if (exp <= nowS) return { ok: false, reason: 'assertion expired' };
  if (exp > nowS + ASSERTION_MAX_TTL_S) return { ok: false, reason: 'assertion exp too far ahead' };

  const material = assertionMaterial(tenant, claim.visitorId, claim.accountId, exp);
  for (const secret of secrets) {
    if (equalStrings(await hmac(secret, material), claim.assertion)) return { ok: true, assurance: 'signed' };
  }
  return { ok: false, reason: 'assertion does not verify' };
}

// src/sdk/identify.ts
// CW25, the client half of identity stitching (docs/architecture/25-identity-stitching.md §4).
// identify() tells the edge which account this browser belongs to; on success the
// browser carries the person's shopper id as its visitor id from then on, and the
// socket reconnects under it, because pushes go to the object named by the id.
// logout() detaches, mints a fresh anonymous id, and reconnects under that. The
// assertion, when the site has an identity secret, is computed by the site's
// backend at login and handed to the page; without one the link is recorded as
// site-assured. A 409 means this browser still carries the previous person's
// shopper id: the SDK logs that person out and links once more with a fresh id.

import type { Core } from './core';
import { freshVisitorId } from './identity';

export interface IdentifyOptions {
  /** HMAC from the site's backend over tenant, visitorId, accountId and exp (see signAssertion). */
  assertion?: string;
  /** Unix seconds the assertion expires, at most 24 h ahead. */
  exp?: number;
  /** Where the sign-in happened, for the audit trail: 'login', 'checkout', … */
  source?: string;
}

export type IdentifyResult =
  | { ok: true; shopperId: string; visitorId: string; outcome: string | null; retried: boolean }
  | { ok: false; status: number; error: string; retried: boolean };

export interface LogoutResult { ok: boolean; status: number; visitorId: string }

export interface Identity {
  identify(accountId: string, options?: IdentifyOptions): Promise<IdentifyResult>;
  logout(): Promise<LogoutResult>;
}

export function createIdentity(core: Core): Identity {
  async function attempt(accountId: string, o: IdentifyOptions) {
    return core.postJson(core.config.paths.identityLink, {
      visitorId: core.visitorId, accountId,
      ...(o.source ? { source: o.source } : {}),
      ...(typeof o.exp === 'number' ? { exp: o.exp } : {}),
      ...(o.assertion ? { assertion: o.assertion } : {}),
    });
  }

  async function logout(): Promise<LogoutResult> {
    const previous = core.visitorId;
    const res = await core.postJson(core.config.paths.identityDetach, { visitorId: previous });
    core.setVisitorId(freshVisitorId(core.host), 'logout');
    return { ok: res.ok, status: res.status, visitorId: core.visitorId };
  }

  async function identify(accountId: string, options: IdentifyOptions = {}): Promise<IdentifyResult> {
    if (!accountId || typeof accountId !== 'string') return { ok: false, status: 0, error: 'accountId required', retried: false };
    let retried = false;
    let res = await attempt(accountId, options);
    if (res.status === 409) {
      // The previous person never logged out. Detach, take a fresh id, link once more.
      await logout();
      retried = true;
      res = await attempt(accountId, options);
    }
    const body = (res.json ?? {}) as { ok?: boolean; carry?: unknown; shopperId?: unknown; outcome?: unknown; error?: unknown };
    const shopperId = typeof body.carry === 'string' ? body.carry : typeof body.shopperId === 'string' ? body.shopperId : null;
    if (!res.ok || body.ok === false || !shopperId) {
      return { ok: false, status: res.status, error: typeof body.error === 'string' ? body.error : 'link refused', retried };
    }
    core.setVisitorId(shopperId, 'identified');
    return { ok: true, shopperId, visitorId: core.visitorId, outcome: typeof body.outcome === 'string' ? body.outcome : null, retried };
  }

  return { identify, logout };
}

// src/routes/identity.ts
// ---------------------------------------------------------------------------
// CW25 — identity stitching (scope appendix §1.12, ledger 20 row 2).
//
//   POST /v1/:tenant/identity/link      the site says who this browser is
//   POST /v1/:tenant/identity/detach    this browser stops being anyone (logout)
//   POST /v1/:tenant/identity/resolve   account id → shopper id, for the warehouse
//   GET  /v1/:tenant/identity/visitor/:visitorId   which person, if any
//   GET  /v1/:tenant/identity/shopper/:shopperId   which browsers, and the history applied
//   POST /v1/:tenant/identity/events    historical rows, JSON or CSV
//   POST /v1/:tenant/identity/erase     the right to be forgotten: links, profiles, ledger rows
//
// Mounted under /v1, so the site-key gate (CW10) covers everything here. The
// link and detach are the SDK's calls and need only the site key, plus the
// signed assertion where the tenant has an identity secret. The rest is the
// data team's and wants the operator token, like the ledger routes.
// ---------------------------------------------------------------------------

import { Hono } from 'hono';
import { z } from 'zod';
import type { Env } from '@/types/env';
import type { TenantVariables } from '@/tenancy/tenant';
import { jwt } from '@/middleware/auth';
import { SessionManager } from '@/services/SessionManager';
import { verifyAssertion } from '@/identity/assertion';
import { linkVisitor, validVisitorId } from '@/identity/link';
import { IdentityStore } from '@/identity/store';
import { isSalted, isShopperId, shopperIdFor } from '@/identity/shopperId';
import { applyHistory, historyRowSchema, parseHistoryCsv, MAX_ROWS } from '@/identity/history';
import { eraseSubject } from '@/identity/erase';
import type { AuthContext } from '@/middleware/auth';

export const identityRoutes = new Hono<{ Bindings: Env; Variables: TenantVariables }>();

const TENANT = /^[a-z0-9][a-z0-9_-]{0,63}$/i;

const linkSchema = z.object({
  visitorId: z.string().trim().min(1).max(200),
  accountId: z.string().trim().min(1).max(200),
  source: z.enum(['login', 'signup', 'checkout', 'import', 'other']).default('login'),
  exp: z.number().int().optional(),
  assertion: z.string().min(1).max(200).optional(),
});

function tenantOf(c: { req: { param(name: string): string | undefined } }): string | null {
  const t = (c.req.param('tenant') ?? '').trim();
  return TENANT.test(t) ? t : null;
}

/**
 * The link. Returns the id the client carries from now on. On the session host
 * the response also sets the session cookie to the person's session, so every
 * tab on this device lands there on its next request without any forwarding.
 */
identityRoutes.post('/:tenant/identity/link', async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  let body: unknown;
  try { body = await c.req.json(); } catch { return c.json({ ok: false, error: 'invalid JSON body' }, 400); }
  const parsed = linkSchema.safeParse(body);
  if (!parsed.success) return c.json({ ok: false, error: parsed.error.issues[0]?.message ?? 'invalid body' }, 400);
  const { visitorId, accountId, source, exp, assertion } = parsed.data;

  if (!validVisitorId(visitorId)) return c.json({ ok: false, error: 'visitorId is not a visitor id' }, 400);
  if (isShopperId(visitorId)) {
    // A browser already carrying a person's id is signed in as that person.
    // Linking it to another account would fold one person into another.
    return c.json({ ok: false, error: 'this browser already carries a shopper id; detach first' }, 409);
  }

  const verdict = await verifyAssertion(c.env, tenant, { visitorId, accountId, exp, assertion });
  if (!verdict.ok) return c.json({ ok: false, error: verdict.reason }, 401);

  const cookieSessionId = new SessionManager(c.env, { tenant }).parseSessionCookies(c.req.header('Cookie') ?? null).sessionId ?? null;
  const result = await linkVisitor(c.env, tenant, { visitorId, accountId, source, assurance: verdict.assurance, cookieSessionId });
  for (const h of result.cookieHeaders) c.header('Set-Cookie', h, { append: true });
  c.header('Cache-Control', 'no-store');
  return c.json({
    ok: true,
    tenant,
    shopperId: result.shopperId,
    visitorId: result.visitorId,
    outcome: result.outcome,
    assurance: result.assurance,
    salted: isSalted(c.env),
    audiences: result.audiences,
    changes: { entered: result.changes.entered, exited: result.changes.exited },
    // What the client does next, spelled out so no SDK has to guess.
    carry: result.shopperId,
  });
});

/**
 * Detach: clear this device's session cookies and nothing else. The person's
 * profile stays whole for their next sign-in; the client mints a fresh
 * anonymous id. Erasure is a different door (session reset), on purpose.
 */
identityRoutes.post('/:tenant/identity/detach', async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const sm = new SessionManager(c.env, { tenant });
  for (const h of sm.clearCookieHeaders()) c.header('Set-Cookie', h, { append: true });
  c.header('Cache-Control', 'no-store');
  return c.json({ ok: true, tenant, detached: true });
});

/** The warehouse's join key for an account, without the warehouse holding the salt. */
identityRoutes.post('/:tenant/identity/resolve', jwt({ required: true }), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  let body: { accountIds?: unknown } = {};
  try { body = await c.req.json(); } catch { return c.json({ ok: false, error: 'invalid JSON body' }, 400); }
  const ids = Array.isArray(body.accountIds) ? body.accountIds.filter((x): x is string => typeof x === 'string' && x.trim() !== '').slice(0, 1000) : [];
  if (ids.length === 0) return c.json({ ok: false, error: 'accountIds: string[] required' }, 400);
  const resolved: Record<string, string> = {};
  for (const id of ids) resolved[id] = await shopperIdFor(c.env, tenant, id);
  return c.json({ ok: true, tenant, salted: isSalted(c.env), resolved });
});

identityRoutes.get('/:tenant/identity/visitor/:visitorId', jwt({ required: true }), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const visitorId = (c.req.param('visitorId') ?? '').trim();
  if (!validVisitorId(visitorId)) return c.json({ ok: false, error: 'visitorId is not a visitor id' }, 400);
  const store = new IdentityStore(c.env.SESSIONS as never, tenant);
  const link = await store.visitorLink(visitorId);
  return c.json({ ok: true, tenant, visitorId, shopperId: isShopperId(visitorId) ? visitorId : (link?.shopperId ?? null), link });
});

identityRoutes.get('/:tenant/identity/shopper/:shopperId', jwt({ required: true }), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const shopperId = (c.req.param('shopperId') ?? '').trim();
  if (!isShopperId(shopperId)) return c.json({ ok: false, error: 'not a shopper id' }, 400);
  const store = new IdentityStore(c.env.SESSIONS as never, tenant);
  const rec = await store.shopper(shopperId);
  if (!rec) return c.json({ ok: false, error: 'unknown shopper' }, 404);
  return c.json({ ok: true, tenant, shopper: rec });
});

/**
 * Historical rows. `application/json` with `{ rows: [...] }`, or `text/csv`
 * with a header row. Each row is validated; a bad row fails the request, a row
 * that names nobody or carries no registry attribute is skipped and reported.
 */
identityRoutes.post('/:tenant/identity/events', jwt({ required: true }), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const ct = (c.req.header('Content-Type') ?? '').toLowerCase();
  let raw: unknown[];
  if (ct.includes('text/csv')) {
    raw = parseHistoryCsv(await c.req.text());
  } else {
    let body: { rows?: unknown } = {};
    try { body = await c.req.json(); } catch { return c.json({ ok: false, error: 'invalid JSON body' }, 400); }
    raw = Array.isArray(body.rows) ? body.rows : [];
  }
  if (raw.length === 0) return c.json({ ok: false, error: 'no rows' }, 400);
  if (raw.length > MAX_ROWS) return c.json({ ok: false, error: `at most ${MAX_ROWS} rows per request` }, 413);
  const parsed = z.array(historyRowSchema).safeParse(raw);
  if (!parsed.success) {
    const issue = parsed.error.issues[0];
    return c.json({ ok: false, error: `row ${String(issue?.path[0] ?? '?')}: ${issue?.message ?? 'invalid'}` }, 400);
  }
  const report = await applyHistory(c.env, tenant, parsed.data);
  return c.json({ ok: true, tenant, ...report });
});

/**
 * CW28. Forget a person, or an unlinked browser: the link table, every
 * profile, and the ledger rows (tombstoned at once, rewritten nightly by the
 * ledger's job). Operator token. The receipt lists what was erased and what
 * this cannot reach.
 */
identityRoutes.post('/:tenant/identity/erase', jwt({ required: true }), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  let body: { visitorId?: unknown; shopperId?: unknown } = {};
  try { body = await c.req.json(); } catch { return c.json({ ok: false, error: 'invalid JSON body' }, 400); }
  const visitorId = typeof body.visitorId === 'string' ? body.visitorId.trim() : '';
  const shopperId = typeof body.shopperId === 'string' ? body.shopperId.trim() : '';
  if (!visitorId && !shopperId) return c.json({ ok: false, error: 'visitorId or shopperId required' }, 400);
  if (visitorId && !validVisitorId(visitorId)) return c.json({ ok: false, error: 'visitorId is not a visitor id' }, 400);
  if (shopperId && !isShopperId(shopperId)) return c.json({ ok: false, error: 'shopperId is not a shopper id' }, 400);
  const actor = (c as unknown as { get: (k: 'auth') => AuthContext | undefined }).get('auth')?.user?.sub ?? 'operator';
  const receipt = await eraseSubject(c.env, tenant, { ...(visitorId ? { visitorId } : {}), ...(shopperId ? { shopperId } : {}) }, actor);
  c.header('Cache-Control', 'no-store');
  return c.json({ ok: true, ...receipt });
});

export interface Env {
  ASSETS: Fetcher;   // static-assets binding (public/) for server-side reads — see wrangler.toml [assets]
  BROWSER?: Fetcher; // Browser Rendering (headless Chromium) for the /__shot verification route
  /** Shared secret for /__shot. UNSET DISABLES THE ROUTE ENTIRELY — see src/routes/shot.ts. */
  SHOT_TOKEN?: string;
  CACHE: KVNamespace;
  SESSIONS: KVNamespace;
  STORAGE: R2Bucket;
  EVENT_QUEUE: Queue;
  ANALYTICS: AnalyticsEngineDataset;
  STATE_MANAGER: DurableObjectNamespace;
  RATE_LIMITER: DurableObjectNamespace;
  PERSONALIZATION_WEBSOCKET: DurableObjectNamespace;
  // Edge Affinity Reflex P2 (doc 16 §6): per-shopper SQLite DO owning the
  // WebSocket + affinity state (wrangler migration v4). Keyed on the STABLE
  // visitor id; used only when REFLEX_HOST = 'do'.
  SHOPPER_REFLEX: DurableObjectNamespace;
  /** Meridian (Opticon) — its own reflex object, never the shared one. */
  MERIDIAN_REFLEX: DurableObjectNamespace;
  /** CW6 — one object per tenant and region: the population's decaying interest vector. Optional so tests and older stamps run without it. */
  REGION_TREND?: DurableObjectNamespace;
  /** Phase 1 — the visitor's own ring of served decisions, with online attribution. */
  DECISION_RING?: DurableObjectNamespace;
  /** Phase 1 — one object per tenant, brand and slot: decayed counts, published as lift snapshots. */
  LEARN_STATS?: DurableObjectNamespace;
  /** Phase 3 (doc 22 §9) — Workers AI, for the `workers_ai` model kind. Absent on this stamp; the kind reports unavailable. */
  AI?: { run(model: string, input: Record<string, unknown>): Promise<unknown> };
  /** CW6 — tenants the hourly cron rolls region snapshots up for, comma-separated. */
  TREND_ROLLUP_TENANTS?: string;
  /**
   * CW28 (doc 22 §15) — the ledger's retention window in days, the span the nightly erasure rewrite
   * walks back from an erasure. Must match the R2 bucket's lifecycle rule. Absent means the design's 90.
   * The number itself is Tapestry's privacy team's to agree.
   */
  LEDGER_RETENTION_DAYS?: string;
  /**
   * Where the platform posts an alert when its five-minute self-check fails or recovers (src/ops/monitor.ts):
   * any URL that accepts a JSON post, a chat webhook or an on-call tool. A secret. Absent means the result is
   * kept and logged but nobody is paged.
   */
  ALERT_WEBHOOK_URL?: string;
  // Opal chat agent (SQLite-backed DO, wrangler migration v3) — reached via
  // routeAgentRequest(/agents/*), not app routes; declared here for Env completeness.
  OpalAgent: DurableObjectNamespace;

  // D1 — Coach demo dataset (ODP profiles + commerce + warehouse-export mirror).
  // Backs the Opal chat's aggregate-then-reason query surface. See
  // docs/architecture/10-d1-schema.md; binding declared in wrangler.toml.
  DB: D1Database;
  /** Operator accounts (doc 30) live in D1 behind src/auth/store; a test hands its own store in here. Never set on a stamp. */
  ACCOUNTS?: import('@/auth/store').AccountStore;

  /**
   * Stamp tenancy (CW1). JSON:
   *   { "provisioned": ["coach","kate-spade"],
   *     "hosts": { "shop.katespade.com": "kate-spade" } }
   * Absent or malformed means the default brand only, which is the safe reading
   * of an unconfigured stamp rather than the permissive one.
   */
  TENANTS?: string;

  /**
   * Whether every shopper action is also written to D1 `demo_events`.
   *
   * That write exists for the demo's operator reset and for Opal's audience
   * sizing. It is also a per-request write into a single-primary SQLite from
   * every edge location, which is the exact pattern doc 22 §18.10 says must
   * never be inherited by a production decision path.
   *
   * 'true' captures, 'false' does not. ABSENT captures only when ENVIRONMENT is
   * not 'production', so the demo keeps working everywhere it works today and
   * production is safe by omission rather than by someone remembering.
   */
  DEMO_EVENT_CAPTURE?: string;

  ENVIRONMENT: string;
  JWT_SECRET: string;
  JWT_ISSUER: string;
  JWT_AUDIENCE: string;
  // Optimizely FX SDK key — NOT secret (datafile at cdn.optimizely.com/datafiles/<key>.json is public).
  OPTIMIZELY_SDK_KEY: string;
  OPTIMIZELY_DATAFILE_URL: string;

  API_KEYS?: string;
  WEBHOOK_ENDPOINTS?: string;
  CDP_ENDPOINTS?: string;

  // Edge Affinity Reflex (docs/architecture/16-edge-affinity-reflex.md) — on by
  // default; set 'false' as the kill-switch. Purely additive attributes/segments.
  REFLEX_ENABLED?: string;
  // Reflex host (doc 16 §6, P2): 'session' (default — state rides the KV session,
  // WS on the relay DO) | 'do' (socket + state + closed-form alarms co-located in
  // the per-shopper ShopperReflex DO). Flag off ⇒ byte-identical default behavior.
  REFLEX_HOST?: 'session' | 'do';
  // ShopperReflex lifecycle/abuse knobs (optional; sensible defaults in the DO):
  // idle self-expiry in days (default 30) and per-minute ingest cap (default 240).
  REFLEX_RETENTION_DAYS?: string;
  REFLEX_RATE_LIMIT_PER_MIN?: string;

  // Bright Hour demo (docs/qvc/QVC-Demo-Design-Brief.md §3): pins the demo epoch
  // offer windows are materialized against, so a rehearsed run replays identically.
  // Absent ⇒ midnight ET at or before the request stamp.
  BRIGHTHOUR_EPOCH_MS?: string;
  BRIGHTHOUR_CLOCK_MULTIPLIER?: string;

  // CW10 — access policy (src/middleware/edgeAccess.ts). 'open' (default) is
  // today's behavior for the shared demo worker; 'enforced' is what the staging
  // stamp sets: SDK keys on /realtime and /v1, JWT on operator writes, CORS
  // answers only CORS_ORIGINS and the page's own origin.
  AUTH_MODE?: 'open' | 'enforced';
  // Comma-separated origins; `*.example.com` matches apex and subdomains. When
  // set, the allow-list applies in either mode. Empty + enforced = same-origin only.
  CORS_ORIGINS?: string;
  // Secret. `tenant:key[|key2],tenant2:key3`; tenant `*` accepts the key anywhere.
  SDK_KEYS?: string;
  // CW25 — identity stitching. IDENTITY_SALT (secret) salts the shopper id; IDENTITY_SECRETS
  // (secret, `tenant:secret[|previous],…`) makes a link require the site's signed assertion.
  IDENTITY_SALT?: string;
  IDENTITY_SECRETS?: string;

  // Connector layer — "real seams, mocked calls" (docs/architecture/05-demo-build-spec.md)
  CONNECTOR_MODE?: 'mock' | 'live';
  // Mode-B decision source, independent of CONNECTOR_MODE:
  //   'mock' (default) — deterministic insight-driven decisions (current demo)
  //   'optimizely'     — real FX SDK over the live datafile (LiveDecisionProvider),
  //                      degrading per-flag to the mock decision when a flag is absent.
  DECISION_SOURCE?: 'mock' | 'optimizely';
  ODP_API_HOST?: string;
  ODP_PUBLIC_KEY?: string;
  OPAL_MCP_ENDPOINT?: string;
  OPTI_ID_TOKEN?: string;
  // Signal-Led Moment DETECT seam — credentials for a LIVE partner social-listening feed.
  // Absent by default: LiveSignalProvider throws NotWiredError and the demo runs on the
  // mocked fixture (src/data/signals.json). DETECT is the only mocked stage of the moment.
  SIGNAL_API_HOST?: string;
  SIGNAL_API_KEY?: string;

  // Opal chat (Gemini) + FX write-tools — provide via wrangler secret / .dev.vars.
  GEMINI_API_KEY: string;
  GEMINI_MODEL?: string;
  GEMINI_IMAGE_MODEL?: string;   // "nano banana" image model for /ai/scene (default gemini-3.1-flash-image)
  OPTIMIZELY_API_TOKEN?: string;
  OPTIMIZELY_PROJECT_ID?: string;
  OPTIMIZELY_ENVIRONMENT?: string;
  OPTIMIZELY_WRITE_ENABLED?: string;
  OPTIMIZELY_WEBHOOK_SECRET?: string;   // HMAC secret for the datafile webhook (X-Hub-Signature)
}

// src/identity/identity.test.ts
//
// The primitives: the id a person gets, the proof the site gives, and the link
// table. Nothing here touches a profile; that is link.test.ts.

import { describe, it, expect } from 'vitest';
import { isSalted, isShopperId, shopperIdFor } from '@/identity/shopperId';
import { secretsFor, signAssertion, verifyAssertion } from '@/identity/assertion';
import { IdentityStore } from '@/identity/store';

class FakeKV {
  store = new Map<string, string>();
  async get(key: string, type?: string) { const r = this.store.get(key); return r === undefined ? null : (type === 'json' ? JSON.parse(r) : r); }
  async put(key: string, value: string) { this.store.set(key, value); }
  async delete(key: string) { this.store.delete(key); }
  async list(o?: { prefix?: string }) { const p = o?.prefix ?? ''; return { keys: [...this.store.keys()].filter((k) => k.startsWith(p)).map((name) => ({ name })) }; }
}

describe('the shopper id', () => {
  it('is deterministic, opaque, and in its own format', async () => {
    const a = await shopperIdFor({}, 'coach', 'acct-1001');
    const b = await shopperIdFor({}, 'coach', 'acct-1001');
    expect(a).toBe(b);
    expect(isShopperId(a)).toBe(true);
    expect(a).not.toContain('1001');
  });

  it('differs by brand for the same account: isolation applied to people', async () => {
    expect(await shopperIdFor({}, 'coach', 'acct-1001')).not.toBe(await shopperIdFor({}, 'kate-spade', 'acct-1001'));
  });

  it('differs with the salt, and says whether one was used', async () => {
    const unsalted = await shopperIdFor({}, 'coach', 'acct-1001');
    const salted = await shopperIdFor({ IDENTITY_SALT: 'pepper' }, 'coach', 'acct-1001');
    expect(salted).not.toBe(unsalted);
    expect(isSalted({})).toBe(false);
    expect(isSalted({ IDENTITY_SALT: 'pepper' })).toBe(true);
  });

  it('trims but never case-folds: two accounts a site treats as distinct stay distinct', async () => {
    expect(await shopperIdFor({}, 'coach', ' A@x.com ')).toBe(await shopperIdFor({}, 'coach', 'A@x.com'));
    expect(await shopperIdFor({}, 'coach', 'A@x.com')).not.toBe(await shopperIdFor({}, 'coach', 'a@x.com'));
  });

  it('recognises only its own format', () => {
    expect(isShopperId('vis-abc')).toBe(false);
    expect(isShopperId('sh_' + 'f'.repeat(32))).toBe(true);
    expect(isShopperId('sh_' + 'f'.repeat(31))).toBe(false);
    expect(isShopperId('SH_' + 'f'.repeat(32))).toBe(false);
  });
});

describe('the assertion', () => {
  const nowMs = 1_800_000_000_000;
  const exp = Math.floor(nowMs / 1000) + 300;
  const claim = { visitorId: 'vis-1', accountId: 'acct-1001', exp };

  it('is not required for a tenant with no secret, and the record says so', async () => {
    const v = await verifyAssertion({}, 'coach', { visitorId: 'vis-1', accountId: 'acct-1001' }, nowMs);
    expect(v).toEqual({ ok: true, assurance: 'site' });
  });

  it('is required once the tenant has a secret', async () => {
    const v = await verifyAssertion({ IDENTITY_SECRETS: 'coach:s3cret' }, 'coach', { visitorId: 'vis-1', accountId: 'acct-1001' }, nowMs);
    expect(v.ok).toBe(false);
  });

  it('verifies what the site signed, and nothing else', async () => {
    const env = { IDENTITY_SECRETS: 'coach:s3cret' };
    const assertion = await signAssertion('s3cret', 'coach', 'vis-1', 'acct-1001', exp);
    expect(await verifyAssertion(env, 'coach', { ...claim, assertion }, nowMs)).toEqual({ ok: true, assurance: 'signed' });
    // A different visitor, account, tenant or expiry: the signature no longer covers the claim.
    expect((await verifyAssertion(env, 'coach', { ...claim, visitorId: 'vis-2', assertion }, nowMs)).ok).toBe(false);
    expect((await verifyAssertion(env, 'coach', { ...claim, accountId: 'acct-1002', assertion }, nowMs)).ok).toBe(false);
    expect((await verifyAssertion({ IDENTITY_SECRETS: 'kate-spade:s3cret' }, 'kate-spade', { ...claim, assertion }, nowMs)).ok).toBe(false);
    expect((await verifyAssertion(env, 'coach', { ...claim, exp: exp + 1, assertion }, nowMs)).ok).toBe(false);
  });

  it('refuses an expired assertion and one dated too far ahead', async () => {
    const env = { IDENTITY_SECRETS: 'coach:s3cret' };
    const past = Math.floor(nowMs / 1000) - 1;
    const pastSig = await signAssertion('s3cret', 'coach', 'vis-1', 'acct-1001', past);
    expect(await verifyAssertion(env, 'coach', { ...claim, exp: past, assertion: pastSig }, nowMs)).toMatchObject({ ok: false, reason: expect.stringMatching(/expired/) });
    const far = Math.floor(nowMs / 1000) + 2 * 24 * 3600;
    const farSig = await signAssertion('s3cret', 'coach', 'vis-1', 'acct-1001', far);
    expect(await verifyAssertion(env, 'coach', { ...claim, exp: far, assertion: farSig }, nowMs)).toMatchObject({ ok: false, reason: expect.stringMatching(/too far/) });
  });

  it('accepts the previous secret during a rotation, and a wildcard secret', async () => {
    const old = await signAssertion('old', 'coach', 'vis-1', 'acct-1001', exp);
    expect((await verifyAssertion({ IDENTITY_SECRETS: 'coach:new|old' }, 'coach', { ...claim, assertion: old }, nowMs)).ok).toBe(true);
    const wild = await signAssertion('any', 'kate-spade', 'vis-1', 'acct-1001', exp);
    expect((await verifyAssertion({ IDENTITY_SECRETS: '*:any' }, 'kate-spade', { ...claim, assertion: wild }, nowMs)).ok).toBe(true);
    expect(secretsFor({ IDENTITY_SECRETS: 'coach:a|b,*:c' }, 'coach')).toEqual(['a', 'b', 'c']);
  });
});

describe('the link table', () => {
  const sh1 = 'sh_' + '1'.repeat(32);
  const sh2 = 'sh_' + '2'.repeat(32);

  it('links, resolves, and is idempotent for the same pair', async () => {
    const store = new IdentityStore(new FakeKV(), 'coach');
    const first = await store.link({ visitorId: 'vis-a', shopperId: sh1, assurance: 'site', source: 'login', salted: false, now: 1000 });
    expect(first.outcome).toBe('linked');
    expect(await store.resolveVisitor('vis-a')).toBe(sh1);
    const again = await store.link({ visitorId: 'vis-a', shopperId: sh1, assurance: 'site', source: 'login', salted: false, now: 2000 });
    expect(again.outcome).toBe('already');
    expect(again.link.linkedAt).toBe(1000);
    expect(again.shopper.visitors).toHaveLength(1);
  });

  it('a shopper id resolves to itself; an unknown visitor to nobody', async () => {
    const store = new IdentityStore(new FakeKV(), 'coach');
    expect(await store.resolveVisitor(sh1)).toBe(sh1);
    expect(await store.resolveVisitor('vis-nobody')).toBeNull();
  });

  it('moves a browser to another person and keeps the trail', async () => {
    const store = new IdentityStore(new FakeKV(), 'coach');
    await store.link({ visitorId: 'vis-a', shopperId: sh1, assurance: 'site', source: 'login', salted: false, now: 1000 });
    const moved = await store.link({ visitorId: 'vis-a', shopperId: sh2, assurance: 'signed', source: 'login', salted: false, now: 5000 });
    expect(moved.outcome).toBe('relinked');
    expect(moved.link.previous).toEqual([{ shopperId: sh1, linkedAt: 1000, until: 5000 }]);
    expect(await store.resolveVisitor('vis-a')).toBe(sh2);
    // Both people remember the browser: the first as history, the second as current.
    expect((await store.shopper(sh1))!.visitors.map((v) => v.visitorId)).toEqual(['vis-a']);
    expect((await store.shopper(sh2))!.visitors.map((v) => v.visitorId)).toEqual(['vis-a']);
  });

  it('two browsers on one person: the cross-device case', async () => {
    const store = new IdentityStore(new FakeKV(), 'coach');
    await store.link({ visitorId: 'vis-phone', shopperId: sh1, assurance: 'site', source: 'login', salted: false });
    await store.link({ visitorId: 'vis-laptop', shopperId: sh1, assurance: 'site', source: 'checkout', salted: false });
    expect((await store.shopper(sh1))!.visitors.map((v) => v.visitorId).sort()).toEqual(['vis-laptop', 'vis-phone']);
  });

  it('is isolated per brand, and never stores the account id', async () => {
    const kv = new FakeKV();
    await new IdentityStore(kv, 'coach').link({ visitorId: 'vis-a', shopperId: sh1, assurance: 'site', source: 'login', salted: false });
    expect(await new IdentityStore(kv, 'kate-spade').resolveVisitor('vis-a')).toBeNull();
    expect(await new IdentityStore(kv, 'coach').resolveVisitor('vis-a')).toBe(sh1);
    expect([...kv.store.keys()].every((k) => k.startsWith('identity:'))).toBe(true);
    await new IdentityStore(kv, 'kate-spade').link({ visitorId: 'vis-b', shopperId: sh2, assurance: 'site', source: 'login', salted: false });
    expect([...kv.store.keys()].some((k) => k.startsWith('t:kate-spade:identity:'))).toBe(true);
  });

  it('records applied history on the person', async () => {
    const store = new IdentityStore(new FakeKV(), 'coach');
    await store.noteHistory(sh1, 3, 1_000, false, 5_000);
    await store.noteHistory(sh1, 2, 900, false, 6_000);
    expect((await store.shopper(sh1))!.history).toEqual({ rows: 5, latestAt: 1_000, appliedAt: 6_000 });
  });
});

// src/routes/identity.test.ts
//
// CW25 through the wire, on the session host: a phone and a laptop browse as
// strangers, both sign in to the same account, and the person is the sum. Then
// the rules around the edges: the assertion, the shopper-id refusal, the shared
// computer, detach, history in both formats, and who may ask what.

import { describe, it, expect, beforeEach } from 'vitest';
import * as jose from 'jose';
import type { Env } from '@/types/env';
import { identityRoutes } from '@/routes/identity';
import { SessionManager } from '@/services/SessionManager';
import { DEFAULT_REFLEX_CONFIG, apply, audienceKey, emptyState, snapshot, type ReflexState } from '@/reflex/core';
import { signAssertion } from '@/identity/assertion';
import { shopperIdFor } from '@/identity/shopperId';

class FakeKV {
  store = new Map<string, string>();
  async get(key: string, type?: string) { const r = this.store.get(key); return r === undefined ? null : (type === 'json' ? JSON.parse(r) : r); }
  async put(key: string, value: string) { this.store.set(key, value); }
  async delete(key: string) { this.store.delete(key); }
  async list(o?: { prefix?: string }) { const p = o?.prefix ?? ''; return { keys: [...this.store.keys()].filter((k) => k.startsWith(p)).map((name) => ({ name })) }; }
}

const cfg = DEFAULT_REFLEX_CONFIG;
const TABBY = audienceKey('line', 'Tabby');

/** Enough of R2 for the ledger's tombstones: put, get, delete, list by prefix. */
class FakeR2 {
  store = new Map<string, string>();
  async put(key: string, body: string) { this.store.set(key, body); }
  async get(key: string) { const v = this.store.get(key); return v === undefined ? null : { text: async () => v }; }
  async delete(key: string) { this.store.delete(key); }
  async list(o: { prefix: string }) { return { objects: [...this.store.keys()].filter((k) => k.startsWith(o.prefix)).map((key) => ({ key })), truncated: false }; }
}

const mkEnv = (over: Record<string, unknown> = {}): Env => ({
  CACHE: new FakeKV(), SESSIONS: new FakeKV(), STORAGE: new FakeR2(), ENVIRONMENT: 'test', CONNECTOR_MODE: 'mock',
  JWT_SECRET: 'w0202-synthetic-route-signing-material', JWT_ISSUER: 'i', JWT_AUDIENCE: 'a', ...over,
} as unknown as Env);
const token = () => new jose.SignJWT({ sub: 'ops' }).setProtectedHeader({ alg: 'HS256' }).setIssuedAt().setIssuer('i').setAudience('a').setExpirationTime('5m').sign(new TextEncoder().encode('w0202-synthetic-route-signing-material'));

const browse = (values: string[], at: number): ReflexState => {
  let s = emptyState(cfg);
  values.forEach((v, i) => { s = apply(s, { action: 'product_view', touches: [{ dim: 'line', value: v }] }, at + i * 1000, cfg).state; });
  return s;
};

let env: Env;
let auth: Record<string, string>;

async function seedDevice(visitorId: string, sessionId: string, values: string[]) {
  const sm = new SessionManager(env);
  // Built a few seconds ago, not at T0: the route merges at Date.now(), and a vector from 2023 is dust by now.
  await sm.createOrUpdateSession(sessionId, visitorId, { reflex: browse(values, Date.now() - 5_000), attributes: { product_views: values.length } });
}

async function call(path: string, init: RequestInit & { json?: unknown } = {}) {
  const headers: Record<string, string> = { ...(init.headers as Record<string, string> ?? {}) };
  let body = init.body;
  if (init.json !== undefined) { headers['Content-Type'] = 'application/json'; body = JSON.stringify(init.json); }
  const res = await identityRoutes.request(path, { ...init, headers, body }, env);
  return { status: res.status, body: (await res.json()) as Record<string, any>, headers: res.headers };
}

beforeEach(async () => {
  env = mkEnv();
  auth = { Authorization: `Bearer ${await token()}` };
});

describe('the link, on the session host', () => {
  it('a phone signs in: the response names the person, sets the cookie, and the old cookie reads the person', async () => {
    await seedDevice('vis-phone', 's-phone', ['Tabby', 'Tabby', 'Tabby']);
    const r = await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-phone', accountId: 'acct-1001' } });
    expect(r.status).toBe(200);
    expect(r.body.outcome).toBe('linked');
    expect(r.body.assurance).toBe('site');
    expect(r.body.shopperId).toBe(await shopperIdFor(env, 'coach', 'acct-1001'));
    expect(r.body.carry).toBe(r.body.shopperId);
    expect(r.body.audiences).toContain(TABBY);
    const cookies = r.headers.get('set-cookie') ?? '';
    expect(cookies).toContain('opt_session_id=');
    expect(cookies).toContain(`opt_user_id=${r.body.shopperId}`);
    expect(cookies).not.toContain('opt_session_id=s-phone');

    const sm = new SessionManager(env);
    expect((await sm.getSession('s-phone'))?.userId).toBe(r.body.shopperId);
  });

  it('a laptop signs in to the same account: cross-device, the person is the sum', async () => {
    await seedDevice('vis-phone', 's-phone', ['Tabby', 'Tabby']);
    await seedDevice('vis-laptop', 's-laptop', ['Rogue', 'Rogue', 'Tabby']);
    const a = await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-phone', accountId: 'acct-1001' } });
    const b = await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-laptop', accountId: 'acct-1001', source: 'checkout' } });
    expect(b.body.shopperId).toBe(a.body.shopperId);
    expect(b.body.outcome).toBe('linked');

    const sm = new SessionManager(env);
    const person = await sm.getSessionByUserId(b.body.shopperId);
    const snap = snapshot(person!.reflex!, Date.now(), cfg);
    expect(Object.keys(snap.dims.line).sort()).toEqual(['Rogue', 'Tabby']);
    expect(person!.attributes.product_views).toBe(5);
    expect(person!.metadata.visitCount).toBe(2);
    // Either browser resolves to the person.
    expect((await sm.getSession('s-phone'))?.userId).toBe(b.body.shopperId);
    expect((await sm.getSession('s-laptop'))?.userId).toBe(b.body.shopperId);
  });

  it('signing in again from the same browser merges nothing and still answers the cookie', async () => {
    await seedDevice('vis-phone', 's-phone', ['Tabby']);
    const a = await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-phone', accountId: 'acct-1001' } });
    const b = await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-phone', accountId: 'acct-1001' } });
    expect(b.body.outcome).toBe('already');
    expect(b.headers.get('set-cookie')).toContain('opt_session_id=');
    const sm = new SessionManager(env);
    expect((await sm.getSessionByUserId(a.body.shopperId))!.attributes.product_views).toBe(1);
  });

  it('a shared computer, second account without a logout: the second person inherits nothing, the first stays whole', async () => {
    // A client that did not adopt the id links the same visitor id to a second
    // account. (One that did adopt it carries a shopper id and gets a 409 below.)
    await seedDevice('vis-shared', 's-shared', ['Tabby', 'Tabby', 'Tabby']);
    const first = await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-shared', accountId: 'acct-1001' } });
    const firstSid = /opt_session_id=([^;]+)/.exec(first.headers.get('set-cookie') ?? '')?.[1];
    const second = await call('/coach/identity/link', {
      method: 'POST', headers: { Cookie: `opt_session_id=${firstSid}` }, json: { visitorId: 'vis-shared', accountId: 'acct-2002' },
    });
    expect(second.body.outcome).toBe('relinked');
    expect(second.body.shopperId).not.toBe(first.body.shopperId);
    expect(second.body.audiences).toEqual([]);
    const secondSid = /opt_session_id=([^;]+)/.exec(second.headers.get('set-cookie') ?? '')?.[1];
    expect(secondSid).not.toBe(firstSid);
    const sm = new SessionManager(env);
    // The device now lands on person 2 (its cookie), the visitor key points there too,
    // and person 1's session was neither forwarded nor emptied.
    expect((await sm.getSession(secondSid!))?.userId).toBe(second.body.shopperId);
    expect(await sm.resolveSessionIdByUserId('vis-shared')).toBe(secondSid);
    const personOne = await sm.readRaw(firstSid!);
    expect(personOne?.forwardTo).toBeUndefined();
    expect(personOne?.reflex?.audiences).toContain(TABBY);
  });

  it('refuses to link a browser that already carries a shopper id', async () => {
    const sh = await shopperIdFor(env, 'coach', 'acct-1001');
    const r = await call('/coach/identity/link', { method: 'POST', json: { visitorId: sh, accountId: 'acct-2002' } });
    expect(r.status).toBe(409);
  });

  it('a browser with no session yet links fine: the person starts empty', async () => {
    const r = await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-fresh', accountId: 'acct-1001' } });
    expect(r.status).toBe(200);
    expect(r.body.audiences).toEqual([]);
    const sm = new SessionManager(env);
    expect(await sm.resolveSessionIdByUserId('vis-fresh')).toBe(await sm.resolveSessionIdByUserId(r.body.shopperId));
  });

  it('validates the body and the tenant', async () => {
    expect((await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-1' } })).status).toBe(400);
    expect((await call('/coach/identity/link', { method: 'POST', json: { visitorId: 't:kate-spade:vis-1', accountId: 'a' } })).status).toBe(400);
    expect((await call('/not a tenant/identity/link', { method: 'POST', json: { visitorId: 'vis-1', accountId: 'a' } })).status).toBe(400);
  });
});

describe('the assertion, when the tenant has a secret', () => {
  beforeEach(() => { env = mkEnv({ IDENTITY_SECRETS: 'coach:s3cret' }); });

  it('refuses an unsigned link, accepts the site-signed one, and records signed assurance', async () => {
    const unsigned = await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-1', accountId: 'acct-1001' } });
    expect(unsigned.status).toBe(401);
    const exp = Math.floor(Date.now() / 1000) + 120;
    const assertion = await signAssertion('s3cret', 'coach', 'vis-1', 'acct-1001', exp);
    const signed = await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-1', accountId: 'acct-1001', exp, assertion } });
    expect(signed.status).toBe(200);
    expect(signed.body.assurance).toBe('signed');
    const forged = await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-1', accountId: 'acct-9999', exp, assertion } });
    expect(forged.status).toBe(401);
  });
});

describe('detach', () => {
  it('clears the cookies and deletes nothing', async () => {
    await seedDevice('vis-phone', 's-phone', ['Tabby']);
    const linked = await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-phone', accountId: 'acct-1001' } });
    const r = await call('/coach/identity/detach', { method: 'POST' });
    expect(r.status).toBe(200);
    expect(r.headers.get('set-cookie')).toContain('opt_session_id=; Max-Age=0');
    const sm = new SessionManager(env);
    expect((await sm.getSessionByUserId(linked.body.shopperId))?.userId).toBe(linked.body.shopperId);
  });
});

describe('the data team’s doors', () => {
  it('resolve, visitor and shopper want the operator token', async () => {
    expect((await call('/coach/identity/resolve', { method: 'POST', json: { accountIds: ['a'] } })).status).toBe(401);
    expect((await call('/coach/identity/visitor/vis-1')).status).toBe(401);
    expect((await call('/coach/identity/shopper/sh_' + 'a'.repeat(32))).status).toBe(401);
    expect((await call('/coach/identity/events', { method: 'POST', json: { rows: [] } })).status).toBe(401);
  });

  it('resolve gives the warehouse its join key', async () => {
    const r = await call('/coach/identity/resolve', { method: 'POST', headers: auth, json: { accountIds: ['acct-1001', 'acct-2002'] } });
    expect(r.status).toBe(200);
    expect(r.body.resolved['acct-1001']).toBe(await shopperIdFor(env, 'coach', 'acct-1001'));
    expect(r.body.salted).toBe(false);
  });

  it('visitor and shopper lookups show the link from both ends', async () => {
    await seedDevice('vis-phone', 's-phone', ['Tabby']);
    const linked = await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-phone', accountId: 'acct-1001' } });
    const v = await call('/coach/identity/visitor/vis-phone', { headers: auth });
    expect(v.body.shopperId).toBe(linked.body.shopperId);
    expect(v.body.link.source).toBe('login');
    const s = await call(`/coach/identity/shopper/${linked.body.shopperId}`, { headers: auth });
    expect(s.body.shopper.visitors.map((x: { visitorId: string }) => x.visitorId)).toEqual(['vis-phone']);
    expect(JSON.stringify(s.body)).not.toContain('acct-1001');
    expect((await call('/coach/identity/visitor/vis-nobody', { headers: auth })).body.shopperId).toBeNull();
    expect((await call('/coach/identity/shopper/sh_' + 'e'.repeat(32), { headers: auth })).status).toBe(404);
  });
});

describe('historical rows', () => {
  it('JSON rows by account id build the person before they ever visit, discounted by their age', async () => {
    const dayAgo = new Date(Date.now() - 24 * 3600_000).toISOString();
    const r = await call('/coach/identity/events', { method: 'POST', headers: auth, json: { rows: [
      { accountId: 'acct-1001', action: 'purchase', at: dayAgo, product: { line: 'Brooklyn', category: 'Bags' } },
      { accountId: 'acct-1001', action: 'purchase', at: Date.now() - 60_000, product: { line: 'Brooklyn' } },
      { accountId: 'acct-1001', action: 'purchase', at: Date.now() - 30_000, product: { line: 'Brooklyn' } },
      { accountId: 'acct-1001', action: 'page_view', at: dayAgo, product: { line: 'Tabby' } },       // no weight
      { accountId: 'acct-1001', action: 'purchase', at: dayAgo, product: { sku: 'x' } },            // nothing the registry reads
    ] } });
    expect(r.status).toBe(200);
    expect(r.body.received).toBe(5);
    expect(r.body.applied).toBe(3);
    expect(r.body.skipped.map((s: { index: number }) => s.index)).toEqual([3, 4]);
    expect(r.body.shoppers).toBe(1);
    const sh = await shopperIdFor(env, 'coach', 'acct-1001');
    expect(r.body.perShopper[0]).toMatchObject({ shopperId: sh, rows: 3, created: true });
    const sm = new SessionManager(env);
    const person = await sm.getSessionByUserId(sh);
    const snap = snapshot(person!.reflex!, Date.now(), cfg);
    // Two purchases a minute ago at weight 5 are plenty; the day-old one is dust.
    expect(snap.dims.line.Brooklyn).toBeGreaterThanOrEqual(cfg.thetaIn);
    expect(person!.metadata.visitCount).toBeUndefined();
    const rec = await call(`/coach/identity/shopper/${sh}`, { headers: auth });
    expect(rec.body.shopper.history.rows).toBe(3);

    // Then she signs in on her phone: the browser folds into the person the import built.
    await seedDevice('vis-phone', 's-phone', ['Tabby']);
    const linked = await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-phone', accountId: 'acct-1001' } });
    expect(linked.body.audiences).toContain(audienceKey('line', 'Brooklyn'));
  });

  it('CSV rows, the way a warehouse exports them', async () => {
    const csv = [
      'account_id,action,at,line,price_usd',
      `acct-1001,purchase,${Math.floor(Date.now() / 1000) - 10},"Tabby",395`,
      `acct-1001,add_to_cart,${Math.floor(Date.now() / 1000) - 5},Tabby,395`,
      `acct-2002,purchase,${new Date(Date.now() - 5000).toISOString()},Rogue,795`,
    ].join('\n');
    const r = await call('/coach/identity/events', { method: 'POST', headers: { ...auth, 'Content-Type': 'text/csv' }, body: csv });
    expect(r.status).toBe(200);
    expect(r.body.applied).toBe(3);
    expect(r.body.shoppers).toBe(2);
    const sm = new SessionManager(env);
    const one = await sm.getSessionByUserId(await shopperIdFor(env, 'coach', 'acct-1001'));
    const snap = snapshot(one!.reflex!, Date.now(), cfg);
    expect(snap.dims.line.Tabby).toBeGreaterThanOrEqual(cfg.thetaIn);
    expect(snap.dims.priceBand?.core).toBeGreaterThan(0); // 395 falls in the core band: derived dimensions work on imports too
  });

  it('rows by visitor id land on the person when the browser was linked, on the browser when not', async () => {
    await seedDevice('vis-phone', 's-phone', ['Tabby']);
    const linked = await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-phone', accountId: 'acct-1001' } });
    const r = await call('/coach/identity/events', { method: 'POST', headers: auth, json: { rows: [
      { visitorId: 'vis-phone', action: 'purchase', at: Date.now() - 1000, product: { line: 'Rogue' } },
      { visitorId: 'vis-stranger', action: 'purchase', at: Date.now() - 1000, product: { line: 'Rogue' } },
    ] } });
    expect(r.body.perShopper.map((p: { shopperId: string }) => p.shopperId).sort()).toEqual([linked.body.shopperId, 'vis-stranger'].sort());
  });

  it('rejects a malformed row, an empty batch, and too many rows', async () => {
    expect((await call('/coach/identity/events', { method: 'POST', headers: auth, json: { rows: [{ action: 'purchase', at: 1 }] } })).status).toBe(400);
    expect((await call('/coach/identity/events', { method: 'POST', headers: auth, json: { rows: [] } })).status).toBe(400);
    const many = Array.from({ length: 1001 }, () => ({ accountId: 'a', action: 'purchase', at: 1 }));
    expect((await call('/coach/identity/events', { method: 'POST', headers: auth, json: { rows: many } })).status).toBe(413);
  });
});

describe('erase: the right to be forgotten (CW28)', () => {
  it('forgets a person: links, both browsers\u2019 profiles, the person\u2019s session, and a tombstone per id', async () => {
    await seedDevice('vis-phone', 's-phone', ['Tabby']);
    await seedDevice('vis-laptop', 's-laptop', ['Rogue']);
    const a = await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-phone', accountId: 'acct-1001' } });
    await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-laptop', accountId: 'acct-1001' } });
    const sh = a.body.shopperId as string;

    const r = await call('/coach/identity/erase', { method: 'POST', headers: auth, json: { visitorId: 'vis-phone' } });
    expect(r.status).toBe(200);
    expect(r.body.shopperId).toBe(sh);
    expect([...r.body.erased].sort()).toEqual([sh, 'vis-laptop', 'vis-phone'].sort());
    expect(r.body.links).toEqual({ visitors: 2, shopper: true });
    expect(r.body.profiles.every((p: { result: string }) => p.result === 'erased' || p.result === 'absent')).toBe(true);
    expect(r.body.ledger.map((l: { id: string; tombstone: string | null }) => [l.id, !!l.tombstone]).every(([, t]: [string, boolean]) => t)).toBe(true);
    expect(r.body.notReached[0]).toMatch(/ODP/);
    expect(r.body.notReached.slice(1)).toEqual([
      'Analytics Engine: historical subject-bearing route events are not erased by this operation; dataset contents, retention and disposition remain unverified',
      'Worker/application logs: historical request, event and subject data are not erased by this operation; other logging paths remain and retention/disposition are unverified',
    ]);
    expect(env.ANALYTICS).toBeUndefined(); // Historical limits are unconditional, not a current-binding check.
    expect(r.body.actor).toBe('ops');

    // Nothing resolves to the person any more, and the person's session is gone.
    const sm = new SessionManager(env);
    expect(await sm.resolveSessionIdByUserId(sh)).toBeNull();
    expect(await sm.resolveSessionIdByUserId('vis-phone')).toBeNull();
    // The browsers' own pre-link records, which only the link remembered, are gone too.
    expect(await sm.readRaw('s-phone')).toBeNull();
    expect(await sm.readRaw('s-laptop')).toBeNull();
    expect((await call('/coach/identity/visitor/vis-laptop', { headers: auth })).body.shopperId).toBeNull();
    expect((await call(`/coach/identity/shopper/${sh}`, { headers: auth })).status).toBe(404);
    // The tombstones the ledger's readers honour at once.
    const r2 = (env as unknown as { STORAGE: FakeR2 }).STORAGE;
    expect([...r2.store.keys()].filter((k) => k.startsWith('erasures/coach/pending/'))).toHaveLength(3);
  });

  it('forgets an unlinked browser on its own', async () => {
    await seedDevice('vis-alone', 's-alone', ['Tabby']);
    const r = await call('/coach/identity/erase', { method: 'POST', headers: auth, json: { visitorId: 'vis-alone' } });
    expect(r.body.shopperId).toBeNull();
    expect(r.body.erased).toEqual(['vis-alone']);
    expect(r.body.profiles[0]).toMatchObject({ id: 'vis-alone', host: 'session', result: 'erased' });
  });

  it('accepts a shopper id directly, and is idempotent', async () => {
    await seedDevice('vis-phone', 's-phone', ['Tabby']);
    const a = await call('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-phone', accountId: 'acct-1001' } });
    const first = await call('/coach/identity/erase', { method: 'POST', headers: auth, json: { shopperId: a.body.shopperId } });
    expect(first.body.links.visitors).toBe(1);
    const again = await call('/coach/identity/erase', { method: 'POST', headers: auth, json: { shopperId: a.body.shopperId } });
    expect(again.status).toBe(200);
    expect(again.body.links.visitors).toBe(0);
    expect(again.body.profiles[0].result).toBe('absent');
    expect(again.body.notReached).toEqual(first.body.notReached);
  });

  it('wants the operator token and a real id', async () => {
    expect((await call('/coach/identity/erase', { method: 'POST', json: { visitorId: 'vis-1' } })).status).toBe(401);
    expect((await call('/coach/identity/erase', { method: 'POST', headers: auth, json: {} })).status).toBe(400);
    expect((await call('/coach/identity/erase', { method: 'POST', headers: auth, json: { shopperId: 'not-a-shopper' } })).status).toBe(400);
  });
});

// src/sdk/identify.test.ts
// CW25, the client half: identify() and logout() against the contract in
// docs/architecture/25-identity-stitching.md §4, with the server faked.

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { createCore } from './core';
import { createIdentity } from './identify';
import { testHost } from './testHost';
import type { ClientConfig, Host } from './types';

// The client's identify() and logout() are one-line delegations to this pair; index.ts pulls the
// browser host (DOM types) into the root typecheck, so the test builds the pair the way the client does.
function createClient(config: ClientConfig, host: Host) {
  const core = createCore(config, host);
  const identity = createIdentity(core);
  return { core, get visitorId() { return core.visitorId; }, connect: () => core.connect(), on: core.on, identify: identity.identify, logout: identity.logout };
}

const LINK = 'https://shop.example/v1/coach/identity/link';
const DETACH = 'https://shop.example/v1/coach/identity/detach';

describe('identify and logout', () => {
  beforeEach(() => { vi.useFakeTimers(); });
  afterEach(() => { vi.useRealTimers(); });

  it('posts the contract, stores the shopper id in both stores, reconnects the socket under it, and says so', async () => {
    const { host, calls, sockets } = testHost({ responses: (url) => (url === LINK ? { ok: true, shopperId: 'shp-9', carry: 'shp-9', outcome: 'linked' } : { ok: true }) });
    const client = createClient({ tenant: 'coach', sdkKey: 'k-1' }, host);
    const before = client.visitorId;
    expect(before).toMatch(/^vis-/);
    client.connect();
    expect(sockets).toHaveLength(1);
    expect(sockets[0]!.url).toContain(`userId=${before}`);
    const changes: unknown[] = [];
    client.on('identity', (c) => changes.push(c));
    const r = await client.identify('acct-42', { source: 'login', exp: 1_800_000_000, assertion: 'sig' });
    expect(r).toEqual({ ok: true, shopperId: 'shp-9', visitorId: 'shp-9', outcome: 'linked', retried: false });
    const link = calls.find((c) => c.url === LINK)!;
    expect(link.init).toMatchObject({ method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json', 'X-SDK-Key': 'k-1' } });
    expect(JSON.parse(link.init!.body!)).toEqual({ visitorId: before, accountId: 'acct-42', source: 'login', exp: 1_800_000_000, assertion: 'sig' });
    expect(client.visitorId).toBe('shp-9');
    expect(host.storage.get('opt_visitor_id')).toBe('shp-9');
    expect(host.cookie.get('opt_visitor_id')).toBe('shp-9');
    expect(sockets).toHaveLength(2);
    expect(sockets[1]!.url).toContain('userId=shp-9');
    expect(changes).toEqual([{ visitorId: 'shp-9', previous: before, reason: 'identified' }]);
    // every later event is the person's
    expect(client.core.envelope('page_view').userId).toBe('shp-9');
  });

  it('a refused link changes nothing', async () => {
    const { host, sockets } = testHost({ responses: () => ({ ok: false, error: 'assertion invalid' }) });
    host.fetch = async () => ({ ok: false, status: 401, json: async () => ({ ok: false, error: 'assertion invalid' }) });
    const client = createClient({ tenant: 'coach' }, host);
    const before = client.visitorId;
    const r = await client.identify('acct-42');
    expect(r).toEqual({ ok: false, status: 401, error: 'assertion invalid', retried: false });
    expect(client.visitorId).toBe(before);
    expect(sockets).toHaveLength(0);
    expect(await client.identify('')).toMatchObject({ ok: false, error: 'accountId required' });
  });

  it('logout detaches, mints a fresh anonymous id, and reconnects under it', async () => {
    const { host, calls, sockets } = testHost({ responses: (url) => (url === LINK ? { ok: true, carry: 'shp-9' } : { ok: true, detached: true }) });
    const client = createClient({ tenant: 'coach' }, host);
    client.connect();
    await client.identify('acct-42');
    expect(client.visitorId).toBe('shp-9');
    const out = await client.logout();
    expect(out.ok).toBe(true);
    expect(calls.find((c) => c.url === DETACH)).toBeTruthy();
    expect(client.visitorId).toMatch(/^vis-/);
    expect(client.visitorId).not.toBe('shp-9');
    expect(host.storage.get('opt_visitor_id')).toBe(client.visitorId);
    expect(sockets[sockets.length - 1]!.url).toContain(`userId=${client.visitorId}`);
  });

  it('on 409 the previous person is logged out and the link is retried once with the fresh id', async () => {
    const { host, calls } = testHost();
    let links = 0;
    host.fetch = async (url, init) => {
      calls.push({ url, init });
      if (url === LINK) {
        links += 1;
        const body = JSON.parse(String(init?.body)) as { visitorId: string };
        if (links === 1) return { ok: false, status: 409, json: async () => ({ ok: false, error: 'this browser already carries a shopper id; detach first' }) };
        return { ok: true, status: 200, json: async () => ({ ok: true, carry: 'shp-2', linkedFrom: body.visitorId }) };
      }
      return { ok: true, status: 200, json: async () => ({ ok: true, detached: true }) };
    };
    host.storage.set('opt_visitor_id', 'shp-1');                              // the previous person never logged out
    const client = createClient({ tenant: 'coach' }, host);
    expect(client.visitorId).toBe('shp-1');
    const r = await client.identify('acct-2');
    expect(r).toMatchObject({ ok: true, shopperId: 'shp-2', retried: true });
    const linkCalls = calls.filter((c) => c.url === LINK).map((c) => JSON.parse(String(c.init?.body)) as { visitorId: string });
    expect(linkCalls[0]!.visitorId).toBe('shp-1');
    expect(linkCalls[1]!.visitorId).toMatch(/^vis-/);                        // never the old shopper id again
    expect(calls.some((c) => c.url === DETACH)).toBe(true);
    expect(client.visitorId).toBe('shp-2');
  });
});

